-- Spoken-only variants, never additional /me text.
local _, addon = ...
local texts = addon.localeData.deDE.generalTexts
texts.COMMEND = { gruppe = { "Euer Einsatz verdient Anerkennung vor allen.", "Nicht jeder Held braucht eine Medaille." }, ziel = { "%s: Nicht jeder Held braucht eine Medaille.", "%s: Euer Einsatz verdient Anerkennung vor allen." } }
texts.DRINK = { gruppe = { "Auf gute Freunde und sichere Heimwege!", "Dieser Krug muss nicht bis morgen reichen." }, ziel = { "%s: Dieser Krug muss nicht bis morgen reichen.", "%s: Auf gute Freunde und sichere Heimwege!" } }
texts.GIGGLE = { gruppe = { "Ich wollte ernst bleiben. Wirklich.", "Das Kichern war stärker als mein Wille." }, ziel = { "%s: Das Kichern war stärker als mein Wille.", "%s: Ich wollte ernst bleiben. Wirklich." } }
texts.PEON = { gruppe = { "Arbeit, Arbeit. Ist denn nie Feierabend?", "Wer hat schon wieder den Auftrag gegeben?" }, ziel = { "%s: Wer hat schon wieder den Auftrag gegeben?", "%s: Arbeit, Arbeit. Ist denn nie Feierabend?" } }
texts.SHINDIG = { gruppe = { "Heute wird gefeiert, bis die Stiefel müde sind!", "Die Musik soll man im ganzen Lager hören." }, ziel = { "%s: Die Musik soll man im ganzen Lager hören.", "%s: Heute wird gefeiert, bis die Stiefel müde sind!" } }
texts.SOB = { gruppe = { "Manchmal tut die Erinnerung einfach weh.", "Ich brauche einen stillen Augenblick." }, ziel = { "%s: Ich brauche einen stillen Augenblick.", "%s: Manchmal tut die Erinnerung einfach weh." } }
texts.VICTORY = { gruppe = { "Das war ein schwer erkämpfter Sieg!", "Vergesst nicht, wer dafür an unserer Seite stand." }, ziel = { "%s: Vergesst nicht, wer dafür an unserer Seite stand.", "%s: Das war ein schwer erkämpfter Sieg!" } }
texts.WEEP = { gruppe = { "Es gibt Abschiede, die viele Tränen kosten.", "Morgen wird die Welt vielleicht leichter sein." }, ziel = { "%s: Morgen wird die Welt vielleicht leichter sein.", "%s: Es gibt Abschiede, die viele Tränen kosten." } }
texts.WELCOME = { gruppe = { "Hier ist noch Platz am Feuer.", "Kommt herein. Gute Gesellschaft wird nie zu viel." }, ziel = { "%s: Kommt herein. Gute Gesellschaft wird nie zu viel.", "%s: Hier ist noch Platz am Feuer." } }
texts.YES = { gruppe = { "Ja, genau so machen wir es!", "Eine klare Antwort spart viele Umwege." }, ziel = { "%s: Eine klare Antwort spart viele Umwege.", "%s: Ja, genau so machen wir es!" } }
texts.CAT = { gruppe = { "Miau. Man muss sich auch einmal verständlich machen.", "Ein wenig Katzenweisheit schadet nie." }, ziel = { "%s: Ein wenig Katzenweisheit schadet nie.", "%s: Miau. Man muss sich auch einmal verständlich machen." } }
texts.CATTY = { gruppe = { "Ein freundliches Wort wäre wohl zu einfach.", "Der Krallenkommentar musste wohl sein." }, ziel = { "%s: Der Krallenkommentar musste wohl sein.", "%s: Ein freundliches Wort wäre wohl zu einfach." } }
texts.CUDDLE = { gruppe = { "Manche Tage verlangen einfach etwas Nähe.", "Ein ruhiger Moment ist mehr wert als Gold." }, ziel = { "%s: Ein ruhiger Moment ist mehr wert als Gold.", "%s: Manche Tage verlangen einfach etwas Nähe." } }
texts.FART = { gruppe = { "Verzeiht, ein unerwarteter Luftzug.", "Dafür kann ich dem Wind die Schuld nicht geben." }, ziel = { "%s: Dafür kann ich dem Wind die Schuld nicht geben.", "%s: Verzeiht, ein unerwarteter Luftzug." } }
texts.PURR = { gruppe = { "Zufriedenheit braucht nicht immer Worte.", "Hier könnte ich eine ganze Weile bleiben." }, ziel = { "%s: Hier könnte ich eine ganze Weile bleiben.", "%s: Zufriedenheit braucht nicht immer Worte." } }
texts.VOLUNTEER = { gruppe = { "Ich übernehme das. Wer kommt mit?", "Wenn jemand anfangen muss, dann eben ich." }, ziel = { "%s: Wenn jemand anfangen muss, dann eben ich.", "%s: Ich übernehme das. Wer kommt mit?" } }
texts.WHINE = { gruppe = { "Weshalb trifft das eigentlich immer mich?", "Ich hätte mir einen einfacheren Auftrag gewünscht." }, ziel = { "%s: Ich hätte mir einen einfacheren Auftrag gewünscht.", "%s: Weshalb trifft das eigentlich immer mich?" } }
texts.WHISTLE = { gruppe = { "Ein fröhliches Lied hilft auf langen Wegen.", "Manche Melodien findet man einfach unterwegs." }, ziel = { "%s: Manche Melodien findet man einfach unterwegs.", "%s: Ein fröhliches Lied hilft auf langen Wegen." } }
texts.WICKED = { gruppe = { "Das ist eine ausgesprochen verwegene Idee.", "Ich sollte vermutlich ein schlechtes Gewissen haben." }, ziel = { "%s: Ich sollte vermutlich ein schlechtes Gewissen haben.", "%s: Das ist eine ausgesprochen verwegene Idee." } }
texts.WICKEDLY = { gruppe = { "Mein Plan hat Ecken. Sehr scharfe Ecken.", "Manche Entscheidungen machen erstaunlich viel Spaß." }, ziel = { "%s: Manche Entscheidungen machen erstaunlich viel Spaß.", "%s: Mein Plan hat Ecken. Sehr scharfe Ecken." } }
texts.WORK = { gruppe = { "Ein guter Tag beginnt mit einer erledigten Aufgabe.", "Die Arbeit ruft. Leider kennt sie meinen Namen." }, ziel = { "%s: Die Arbeit ruft. Leider kennt sie meinen Namen.", "%s: Ein guter Tag beginnt mit einer erledigten Aufgabe." } }
texts.WRATH = { gruppe = { "Genug! Jetzt hört die Nachsicht auf.", "Ein Zorn, der nicht handelt, ist nur Lärm." }, ziel = { "%s: Ein Zorn, der nicht handelt, ist nur Lärm.", "%s: Genug! Jetzt hört die Nachsicht auf." } }
texts.YAWN = { gruppe = { "Ich könnte an diesem Ort drei Tage schlafen.", "Eine Rast würde jetzt Großes bewirken." }, ziel = { "%s: Eine Rast würde jetzt Großes bewirken.", "%s: Ich könnte an diesem Ort drei Tage schlafen." } }
texts.BURP = { gruppe = { "Der Eintopf hat sich gerade verabschiedet.", "Das war lauter, als ich beabsichtigt hatte." }, ziel = { "%s: Das war lauter, als ich beabsichtigt hatte.", "%s: Der Eintopf hat sich gerade verabschiedet." } }
texts.BLOOD = { gruppe = { "Das ist mehr Blut, als ich sehen wollte.", "Eine Pause und ein Verband wären klug." }, ziel = { "%s: Eine Pause und ein Verband wären klug.", "%s: Das ist mehr Blut, als ich sehen wollte." } }
texts.HAIL = { gruppe = { "Mein Gruß gilt allen, die hier Wache halten.", "Ehre jenen, die den Weg freihalten." }, ziel = { "%s: Ehre jenen, die den Weg freihalten.", "%s: Mein Gruß gilt allen, die hier Wache halten." } }
texts.RDY = { gruppe = { "Bereit! Sagt nur, wann es losgeht.", "Alles sitzt, und die Richtung ist klar." }, ziel = { "%s: Alles sitzt, und die Richtung ist klar.", "%s: Bereit! Sagt nur, wann es losgeht." } }
